def parse_time(string: str) ->Optional[mod_datetime.datetime]:
    if not string:
        return None
    match = RE_TIMESTAMP.match(string)
    if not match:
        return None
    try:
        year = int(match.group(1))
        month = int(match.group(2))
        day = int(match.group(3))
        hour = int(match.group(4))
        minute = int(match.group(5))
        second = int(match.group(6))
        microsecond = 0
        if match.group(7):
            microsecond_str = match.group(7)[1:]  # Remove the leading dot
            # Pad with zeros to ensure 6 digits for microseconds
            microsecond_str = (microsecond_str + '000000')[:6]
            microsecond = int(microsecond_str)
        tz_string = match.group(8)
        tz = None
        if tz_string:
            if tz_string == 'Z':
                tz = SimpleTZ()
            else:
                tz = SimpleTZ(tz_string)
        return mod_datetime.datetime(year, month, day, hour, minute, second,
                                     microsecond, tzinfo=tz)
    except Exception:
        return None
